CREATE OR REPLACE FUNCTION trip_private.content_text_safe(p_text text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(p_text,'') !~* '(hangover|drunk|wasted|blackout|chang toast|starbucks|mcdonald|coca.cola|budweiser|nigg[a-z]*|fagg?[a-z]*|cunt[a-z]*|retard[a-z]*|rape[a-z]*|nazi[a-z]*|dress (up )?like (a|an|the) [a-z]+)' $$; CREATE OR REPLACE FUNCTION trip_private.guard_generated_content() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_text text; BEGIN v_text := CASE TG_TABLE_NAME WHEN 'game_cards' THEN NEW.prompt WHEN 'weekly_question_pool' THEN NEW.prompt WHEN 'at_home_pack_items' THEN coalesce(NEW.title,'')||' '||coalesce(NEW.body,'') WHEN 'content_variants' THEN NEW.text WHEN 'security_missions' THEN coalesce(NEW.title,'')||' '||coalesce(NEW.text,'') ELSE '' END; IF NOT trip_private.content_text_safe(v_text) THEN RAISE EXCEPTION 'Content did not pass the safety check'; END IF; RETURN NEW; END $$; CREATE TRIGGER guard_game_cards_text BEFORE INSERT OR UPDATE OF prompt ON public.game_cards FOR EACH ROW EXECUTE FUNCTION trip_private.guard_generated_content(); CREATE TRIGGER guard_question_pool_text BEFORE INSERT OR UPDATE OF prompt ON public.weekly_question_pool FOR EACH ROW EXECUTE FUNCTION trip_private.guard_generated_content(); CREATE TRIGGER guard_pack_text BEFORE INSERT OR UPDATE OF title,body ON public.at_home_pack_items FOR EACH ROW EXECUTE FUNCTION trip_private.guard_generated_content(); CREATE TRIGGER guard_variants_text BEFORE INSERT OR UPDATE OF text ON public.content_variants FOR EACH ROW EXECUTE FUNCTION trip_private.guard_generated_content(); CREATE TRIGGER guard_missions_text BEFORE INSERT OR UPDATE OF title,text ON public.security_missions FOR EACH ROW EXECUTE FUNCTION trip_private.guard_generated_content();